INSERT INTO public.knowledge_articles (title, content, summary, category, emoji, read_time_minutes, tags, thumbnail_url, is_published, author_name, view_count, created_at, updated_at)
SELECT * FROM (VALUES
('Crate Training: Creating a Safe Haven', 'Crate training utilizes a dog''s natural denning instinct. A crate helps with potty training and provides a safe space when they feel overwhelmed. Feed your dog inside the crate to build positive associations. Never use the crate as a ''time-out'' spot, as this can lead to anxiety and a reluctance to enter the space voluntarily.', 'Why a crate is a management tool, not a punishment, for your dog.', 'Canine', '🏠', 10, ARRAY['dogs','training','puppy','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:30:00Z'::timestamptz, '2026-05-15T00:30:00Z'::timestamptz),
('Understanding Feline Hyperesthesia', 'Feline Hyperesthesia is characterized by sudden bursts of frantic grooming, skin rippling, or tail chasing. It can be triggered by stress or physical touch. Creating a calm environment and consulting your vet about possible nerve-related pain or anti-anxiety treatments can help manage this often-misunderstood condition.', 'Recognizing the ''rippling skin'' syndrome and how to support your cat.', 'Feline', '🙀', 8, ARRAY['cats','health','behavior','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:35:00Z'::timestamptz, '2026-05-15T00:35:00Z'::timestamptz),
('The Importance of Brine Shrimp in Fish Diets', 'Brine shrimp are packed with protein and fatty acids that enhance growth and coloration in tropical fish. They are especially vital for conditioning breeding pairs and feeding young fry. While flakes are a good staple, supplementing with brine shrimp twice a week replicates a natural diet and keeps your fish active and vibrant.', 'Why live or frozen brine shrimp are the gold standard for fish health.', 'Aquatic', '🦐', 5, ARRAY['fish','food','health','breeding']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:40:00Z'::timestamptz, '2026-05-15T00:40:00Z'::timestamptz),
('Safe Flight: Wing Clipping vs. Free Flight', 'Wing clipping can prevent escapes and window collisions but limits a bird''s exercise and natural flight response. Free flight requires a ''bird-proofed'' home with no ceiling fans or open pots of water. Whichever you choose, safety is paramount. Ensure your choice fits your bird''s temperament and your ability to supervise their activity.', 'Pros and cons of managing your bird’s ability to fly indoors.', 'Avian', '🪽', 11, ARRAY['birds','safety','training','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:45:00Z'::timestamptz, '2026-05-15T00:45:00Z'::timestamptz),
('Housing Multiple Guinea Pigs: Social Dynamics', 'Guinea pigs are extremely social and can become depressed if kept alone. When introducing a new pair, use a neutral area with plenty of food to distract them. Small amounts of rumbling or mounting are normal as they establish a hierarchy. Ensure their cage is large enough for two to prevent territorial bickering over food bowls.', 'Why guinea pigs are happier in pairs and how to introduce a new friend.', 'Small Pet', '🐹', 9, ARRAY['guinea pigs','life','behavior','bonding']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:50:00Z'::timestamptz, '2026-05-15T00:50:00Z'::timestamptz),
('Seasonal Shedding: Managing Pet Hair at Home', 'Most pets shed more heavily twice a year as they transition between summer and winter coats. Daily brushing during these periods is the best way to manage hair before it hits your floor. Use a de-shedding tool like a Furminator for double-coated breeds, and ensure their diet includes Omega-3 fatty acids to support skin health during the transition.', 'Tips for dealing with the ''blow out'' of undercoats during weather shifts.', 'General', '🧹', 6, ARRAY['grooming','life','maintenance','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:55:00Z'::timestamptz, '2026-05-15T00:55:00Z'::timestamptz),
('Identifying Common Skin Allergies in Indian Dogs', 'Indian climate conditions often exacerbate skin issues in dogs. Hotspots and fungal infections are common during high humidity. If your dog is constantly licking their paws or scratching their ears, it may be an allergy to local grass or dust mites. Medicated baths and a grain-free diet adjustment often provide significant relief.', 'From environmental pollen to flea-bite dermatitis—how to spot and treat itchy skin.', 'Canine', '🐕', 7, ARRAY['dogs','health','allergies','India']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:00:00Z'::timestamptz, '2026-05-15T01:00:00Z'::timestamptz),
('Loose Leash Walking: Stop the Pulling', 'Pulling on the leash is a self-rewarding behavior for dogs because it gets them where they want to go faster. To stop it, become a ''statue'' the moment the leash goes taut. Only move forward when the leash slacks. Consistent reward for staying by your side will eventually teach your dog that a loose leash is the fastest way to the park.', 'Mastering the art of the peaceful walk without being dragged down the street.', 'Canine', '🦮', 9, ARRAY['dogs','training','life','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:05:00Z'::timestamptz, '2026-05-15T01:05:00Z'::timestamptz),
('Feline Dental Health: Preventing Stomatitis', 'Dental disease in cats can lead to systemic infections affecting the heart and kidneys. Signs include bad breath, drooling, or dropping food. While brushing with feline-specific toothpaste is best, dental treats and water additives can also help reduce plaque buildup. Annual vet check-ups are essential for professional scaling.', 'Why oral hygiene is the most overlooked aspect of cat care and how to start brushing.', 'Feline', '🦷', 6, ARRAY['cats','health','hygiene','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:10:00Z'::timestamptz, '2026-05-15T01:10:00Z'::timestamptz),
('The Mystery of the ''Zoomies'': Cat Frenetic Activity', 'Frenetic Random Activity Periods (FRAPs), or ''zoomies,'' are a way for cats to expend pent-up energy. This is especially common in indoor cats with limited hunting opportunities. To minimize midnight sprints, engage your cat in a high-intensity play session with a feather wand right before your bedtime followed by a small snack.', 'Why your cat suddenly sprints across the room at 3 AM and how to manage it.', 'Feline', '💨', 5, ARRAY['cats','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:15:00Z'::timestamptz, '2026-05-15T01:15:00Z'::timestamptz),
('Controlling Blue-Green Algae (Cyanobacteria)', 'Cyanobacteria isn''t actually algae; it''s a bacteria that thrives in low-nitrate and poor-flow environments. It forms a thick, foul-smelling sheet over plants and substrate. Treatment involves manual removal, increasing water flow, and sometimes a complete ''blackout'' of the tank for 3 days to starve the bacteria of light.', 'Identifying the slimy green coating in your tank and how to safely eradicate it.', 'Aquatic', '🦠', 8, ARRAY['aquarium','maintenance','health','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:20:00Z'::timestamptz, '2026-05-15T01:20:00Z'::timestamptz),
('The Best Nano Fish for Small Aquariums', 'For smaller setups, look for ''Nano'' species like Chili Rasboras, Celestial Pearl Danios, or Endlers Livebearers. These fish stay under an inch in length and have a small bio-load. Even in small tanks, filtration and consistent water changes are paramount, as parameters can shift rapidly in low-volume environments.', 'Species that thrive in tanks under 10 gallons without feeling cramped.', 'Aquatic', '🐠', 7, ARRAY['aquarium','setup','species','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:25:00Z'::timestamptz, '2026-05-15T01:25:00Z'::timestamptz),
('Parrot Hormones: Managing Springtime Aggression', 'In spring, increased daylight can trigger breeding hormones in parrots, leading to biting, screaming, or egg-laying. Manage this by ensuring your bird gets 12 hours of uninterrupted darkness and avoiding ''mushy'' warm foods. Avoid stroking your bird''s back or wings, as this can be interpreted as mating behavior.', 'How changes in daylight trigger hormonal shifts and how to keep your bird calm.', 'Avian', '🦜', 10, ARRAY['birds','behavior','training','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:30:00Z'::timestamptz, '2026-05-15T01:30:00Z'::timestamptz),
('The Importance of Cuttlebone for Birds', 'Cuttlebone is a natural source of calcium carbonate, vital for bone health and egg production in female birds. Gnawing on the hard surface also helps keep a bird''s beak trimmed and sharp. If your bird ignores the bone, try scraping some of the powder onto their fresh vegetables or fruit to ensure they get the nutrients.', 'Providing essential calcium and beak maintenance for all avian species.', 'Avian', '🦴', 4, ARRAY['birds','nutrition','health','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:35:00Z'::timestamptz, '2026-05-15T01:35:00Z'::timestamptz),
('Ferret Proofing: Living with ''Carpet Sharks''', 'Ferrets are notorious for getting stuck in reclining chairs, dishwashers, and behind cabinets. Seal all holes larger than one inch with hardware cloth or wood. Be extremely careful with laundry, as ferrets love to sleep in piles of clothes and can accidentally be thrown into the washing machine. Constant vigilance is the price of ferret ownership.', 'If a ferret''s head fits, their body fits—how to secure your home for these escape artists.', 'Small Pet', '🦦', 8, ARRAY['ferrets','safety','home','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:40:00Z'::timestamptz, '2026-05-15T01:40:00Z'::timestamptz),
('Flystrike in Rabbits: A Summer Emergency', 'Flystrike occurs when flies lay eggs on a rabbit’s damp or soiled fur, which hatch into larvae that burrow into the skin. This can happen in hours and is often fatal. Check your rabbit''s rear end twice daily in summer. Keep hutches clean and use fly screens. If you see any maggots, it is a life-threatening emergency—see a vet immediately.', 'Recognizing the signs of this rapid and deadly parasitic infestation.', 'Small Pet', '🪰', 6, ARRAY['rabbits','health','safety','emergency']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:45:00Z'::timestamptz, '2026-05-15T01:45:00Z'::timestamptz),
('Interpreting Pet Food Labels: The 95% Rule', 'Pet food labels follow strict naming conventions. For example, ''Beef for Dogs'' must contain 95% beef, while ''Beef Dinner'' or ''Beef Entrée'' only requires 25%. If the label says ''With Beef,'' it only needs 3%. Always look at the ingredient list first; the first three items should be high-quality protein sources, not fillers like corn or soy.', 'Understanding the marketing jargon on your pet''s kibble bag.', 'General', '🏷️', 11, ARRAY['food','nutrition','generic','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:50:00Z'::timestamptz, '2026-05-15T01:50:00Z'::timestamptz),
('Coping with the Loss of a Pet', 'The bond with a pet is profound, and the grief following their passing is real and valid. Allow yourself time to mourn and consider creating a memorial, such as a photo album or planting a tree in their favorite spot. Surround yourself with supportive people who understand the unique pain of losing a non-human family member.', 'Navigating the stages of grief and honoring the memory of a beloved companion.', 'General', '🌈', 8, ARRAY['life','grief','generic','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T01:55:00Z'::timestamptz, '2026-05-15T01:55:00Z'::timestamptz),
('Indian Spices: What''s Safe for Your Dog?', 'While turmeric is celebrated for its anti-inflammatory properties, other common Indian spices like onions and garlic (in large amounts) are toxic to dogs. Avoid giving your dog food seasoned with ''masala'' blends. A tiny pinch of ginger can help with digestion, but always keep your pet''s diet bland to avoid pancreatitis and gastrointestinal distress.', 'Navigating the kitchen cabinet—identifying which spices are beneficial and which are toxic.', 'Canine', '🌶️', 6, ARRAY['dogs','nutrition','safety','India']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:00:00Z'::timestamptz, '2026-05-14T22:00:00Z'::timestamptz),
('Stop the Bark: Managing Doorbell Reactivity', 'Doorbell barking is often a mix of excitement and territorial instinct. To manage this, practice ''place'' training where your dog goes to a specific mat when the bell rings. Reward them with high-value treats for staying calm. Desensitize them by ringing the bell yourself during quiet hours and rewarding silence, eventually breaking the cycle of noise.', 'Training techniques to calm your dog when visitors arrive at your home.', 'Canine', '🔔', 8, ARRAY['dogs','training','behavior','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:05:00Z'::timestamptz, '2026-05-14T22:05:00Z'::timestamptz),
('Cat Acne: Causes and Simple Cures', 'Feline acne often appears as black ''comedones'' on the chin. A leading cause is the use of plastic food bowls, which harbor bacteria in microscopic scratches. Switching to stainless steel or ceramic bowls and cleaning them daily can often clear up mild cases. For severe inflammation, your vet may prescribe medicated wipes or a topical gel.', 'Why those black specks on your cat''s chin might be more than just dirt.', 'Feline', '🧴', 5, ARRAY['cats','health','hygiene','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:10:00Z'::timestamptz, '2026-05-14T22:10:00Z'::timestamptz),
('Introducing a Second Cat: The Scent Swap', 'Never introduce two cats face-to-face immediately. Start with ''scent swapping''—rub a cloth on one cat and place it in the other''s room. This allows them to get used to each other''s presence without physical threat. Once they stop reacting negatively to the scent, allow visual contact through a screen or glass before a full supervised introduction.', 'How to prevent territorial wars when expanding your feline family.', 'Feline', '🤝', 9, ARRAY['cats','behavior','life','training']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:15:00Z'::timestamptz, '2026-05-14T22:15:00Z'::timestamptz),
('Aquarium Surface Film: Causes and Fixes', 'Surface film is usually a buildup of proteins and organic waste that prevents gas exchange, lowering oxygen levels for your fish. It can be caused by overfeeding or lack of surface agitation. A surface skimmer is the most effective tool for removal, but simply pointing your filter output toward the surface can also break up the film.', 'Why that oily layer on top of your water is bad and how to remove it.', 'Aquatic', '🌊', 6, ARRAY['aquarium','maintenance','water quality','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:20:00Z'::timestamptz, '2026-05-14T22:20:00Z'::timestamptz),
('Cultivating Java Moss: The Beginner''s Moss', 'Java Moss is nearly indestructible and provides excellent cover for baby fish and shrimp. To grow it, tie small clumps to driftwood or rocks using fishing line or cotton thread. It doesn''t require high light or CO2. Over time, it will attach itself and grow into a lush, green carpet that helps stabilize water parameters.', 'Tips for growing this versatile aquatic plant on rocks and wood.', 'Aquatic', '🌿', 5, ARRAY['aquarium','plants','beginner','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:25:00Z'::timestamptz, '2026-05-14T22:25:00Z'::timestamptz),
('Avian Enrichment: The Power of Foraging', 'In the wild, birds spend most of their day searching for food. You can replicate this by wrapping treats in paper, hiding seeds in cardboard boxes, or using specialized foraging toys. This mental stimulation prevents boredom and common behavioral issues like feather plucking or excessive screaming. Start simple and increase the difficulty as your bird learns.', 'Why your bird needs to ''work'' for its food to stay mentally healthy.', 'Avian', '🦜', 7, ARRAY['birds','training','behavior','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:30:00Z'::timestamptz, '2026-05-14T22:30:00Z'::timestamptz),
('Safe Wood for Bird Perches', 'Natural branches are far better for a bird''s feet than uniform dowel perches. Safe woods include apple, manzanita, and eucalyptus (ensure they are pesticide-free). Avoid cedar, cherry, and oak, which can contain toxic tannins or resins. Always scrub and bake natural wood at a low temperature to kill any wild bacteria before adding it to the cage.', 'Which natural branches are safe for your parrot to chew and stand on?', 'Avian', '🌳', 6, ARRAY['birds','safety','home','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:35:00Z'::timestamptz, '2026-05-14T22:35:00Z'::timestamptz),
('Rat Nutrition: Beyond the Lab Block', 'While high-quality lab blocks should be the base of a rat''s diet, they also need variety. Fresh vegetables like broccoli, peas, and carrots, along with small amounts of cooked grains or pasta, provide essential nutrients. Avoid sugary treats and high-fat seeds, as rats are prone to obesity and tumors. Always provide clean, fresh water daily.', 'Creating a balanced diet for these highly intelligent small mammals.', 'Small Pet', '🐀', 8, ARRAY['rats','food','nutrition','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:40:00Z'::timestamptz, '2026-05-14T22:40:00Z'::timestamptz),
('Managing Summer Heat for Guinea Pigs', 'Guinea pigs are very sensitive to heat and can easily suffer from heatstroke. Keep their enclosure in the coolest part of the house, away from direct sunlight. Provide ''ice pods'' or frozen water bottles wrapped in towels for them to lie against. On extremely hot days, a small fan nearby (not pointing directly at them) can help circulate air.', 'Keeping your small pets cool when temperatures rise in India.', 'Small Pet', '🌡️', 6, ARRAY['guinea pigs','safety','health','India']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:45:00Z'::timestamptz, '2026-05-14T22:45:00Z'::timestamptz),
('Pet Insurance: Is It Worth the Premium?', 'Pet insurance in India is growing, offering coverage for accidents, surgeries, and some illnesses. While monthly premiums can add up, they provide peace of mind for high-cost emergencies. Carefully read the exclusions, such as pre-existing conditions or breed-specific hereditary issues. For many, an ''emergency savings account'' is a viable alternative if insurance isn''t a fit.', 'Evaluating the pros and cons of insurance plans for your pets in India.', 'General', '🛡️', 10, ARRAY['finance','safety','generic','India']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:50:00Z'::timestamptz, '2026-05-14T22:50:00Z'::timestamptz),
('How to Safely Cut Your Pet''s Nails', 'Trimming nails is essential to prevent painful overgrowth. The key is to avoid the ''quick,'' the blood vessel inside the nail. For pets with dark nails, trim in tiny increments. If you do nick the quick, use styptic powder or cornstarch to stop the bleeding. Constant praise and treats make the process much easier for everyone involved.', 'A stress-free guide to paw maintenance for dogs, cats, and small pets.', 'General', '✂️', 7, ARRAY['grooming','training','safety','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:55:00Z'::timestamptz, '2026-05-14T22:55:00Z'::timestamptz),
('Swimming Safety: Can All Dogs Swim?', 'While some breeds have webbing between their toes, others, like bulldogs or pugs, struggle due to their weight distribution and flat faces. Always use a canine life jacket for first-timers. Introduce them to shallow water where they can touch the ground, and never throw a dog into a pool, as the trauma can create a lifelong fear of water.', 'Debunking the myth that every dog is a natural swimmer and how to introduce water safely.', 'Canine', '🏊', 7, ARRAY['dogs','safety','training','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:00:00Z'::timestamptz, '2026-05-15T02:00:00Z'::timestamptz),
('The Benefits of Puzzle Feeders for Dogs', 'A dog eating from a bowl finishes in minutes, but a puzzle feeder can extend mealtime to twenty minutes. This mental engagement tires them out more than a short walk. It also prevents ''bloat'' in fast eaters. You can use rubber toys stuffed with wet food or snuffle mats that hide dry kibble within fabric strips to engage their sense of smell.', 'Why making your dog ''hunt'' for their kibble is the ultimate boredom buster.', 'Canine', '🧩', 6, ARRAY['dogs','training','nutrition','behavior']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:05:00Z'::timestamptz, '2026-05-15T02:05:00Z'::timestamptz),
('The Dangers of Lilies for Cats', 'Many cat owners are unaware that the entire lily plant—pollen, leaves, and even the water in the vase—is highly toxic. Ingestion of a tiny amount can lead to acute kidney failure within hours. If you suspect your cat has nibbled a lily, it is a critical emergency. Opt for cat-safe flowers like Roses or Orchids to keep your home floral and safe.', 'Why this common household flower is a silent killer for your feline friends.', 'Feline', '🚫', 5, ARRAY['cats','safety','health','home']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:10:00Z'::timestamptz, '2026-05-15T02:10:00Z'::timestamptz),
('Deciphering Your Cat''s Tail Language', 'A cat’s tail is a highly expressive mood indicator. A high, vibrating tail signals extreme happiness or greeting. A tail tucked between legs indicates fear, while a puffed-up ''bottlebrush'' tail is a sign of aggression or being startled. Understanding these subtle cues helps you respect your cat''s boundaries and strengthen your bond.', 'From the ''question mark'' to the ''bottlebrush''—what your cat is trying to tell you.', 'Feline', '🐈', 8, ARRAY['cats','behavior','communication','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:15:00Z'::timestamptz, '2026-05-15T02:15:00Z'::timestamptz),
('Choosing the Right Substrate for Your Aquarium', 'The choice of substrate dictates what you can grow and keep. Sand is vital for bottom-dwellers with sensitive barbels, like Corydoras. Gravel is easier to clean and great for general setups. For a heavily planted ''Iwagumi'' or ''Nature Style'' tank, an active soil substrate provides the nutrients necessary for root-feeding plants and helps lower pH levels.', 'Sand vs. Gravel vs. Soil: Which one is right for your fish and plants?', 'Aquatic', '🏖️', 9, ARRAY['aquarium','setup','plants','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:20:00Z'::timestamptz, '2026-05-15T02:20:00Z'::timestamptz),
('How to Handle an Aquarium Power Outage', 'The biggest threat during a power outage isn''t temperature, but oxygen depletion and filter bacteria death. Do not feed your fish, as this uses up oxygen. Use a battery-operated air pump to keep the surface agitated. If the outage lasts hours, wrap the tank in blankets to retain heat and keep your filter media damp with tank water so the beneficial bacteria survive.', 'Emergency steps to keep your fish alive when the lights go out.', 'Aquatic', '🔌', 7, ARRAY['aquarium','emergency','safety','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:25:00Z'::timestamptz, '2026-05-15T02:25:00Z'::timestamptz),
('The Basics of Bird Clicker Training', 'Clicker training is an incredibly effective way to communicate with birds. The ''click'' marks the exact moment the bird does something right, followed by a treat. Start by ''charging the clicker'' (click then treat) until they associate the sound with a reward. You can then use it to teach ''target training,'' where the bird touches a stick for a reward, the foundation for all tricks.', 'Using positive reinforcement to teach your bird tricks and good manners.', 'Avian', '🖱️', 10, ARRAY['birds','training','behavior','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:30:00Z'::timestamptz, '2026-05-15T02:30:00Z'::timestamptz),
('Night Frights in Cockatiels: Prevention', 'Cockatiels are prone to ''night frights,'' where they panic in the dark and fly blindly into cage bars. This is often triggered by shadows or sudden noises. To prevent injury, use a dim nightlight near the cage so they can see their surroundings if they wake up. Ensure the cage is in a quiet area and is partially covered to provide a sense of security.', 'Why your bird might thrash in the dark and how to create a calm sleeping space.', 'Avian', '🌙', 6, ARRAY['birds','safety','behavior','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:35:00Z'::timestamptz, '2026-05-15T02:35:00Z'::timestamptz),
('Chinchilla Dust Baths: A Grooming Guide', 'Chinchillas have incredibly dense fur that traps moisture, making water baths dangerous as they can lead to skin rot. Instead, they roll in volcanic ash or specialized ''chinchilla dust'' to remove oils. Provide a dust bath 2-3 times a week for about 15 minutes. If their fur looks flat or oily, they may need more frequent sessions to maintain their plush coat.', 'Why you should never use water and how to set up a proper dust station.', 'Small Pet', '☁️', 5, ARRAY['small pets','grooming','hygiene','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:40:00Z'::timestamptz, '2026-05-15T02:40:00Z'::timestamptz),
('The Essential Guide to Rabbit Hay', 'A rabbit''s digestive system is built for constant fiber. Timothy hay or orchard grass is essential for keeping their gut moving and wearing down their ever-growing teeth. Alfalfa hay is only for young rabbits or nursing mothers due to its high calcium. If a rabbit stops eating hay for even 12 hours, it can lead to GI Stasis—a life-threatening condition.', 'Why 80% of your rabbit''s diet must be hay and how to choose the best type.', 'Small Pet', '🌾', 7, ARRAY['rabbits','nutrition','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:45:00Z'::timestamptz, '2026-05-15T02:45:00Z'::timestamptz),
('DIY First Aid Kit for Pet Owners', 'Every pet owner should have a basic kit ready. Essential items include: self-adhesive bandages (that don''t stick to fur), saline solution for eye/wound flushing, styptic powder for nail nicks, a digital thermometer, and tweezers for tick removal. Also, keep the number of your local 24/7 emergency vet taped to the inside of the lid for quick access.', 'What to keep in your home medical box for minor injuries and stabilization.', 'General', '🩹', 11, ARRAY['safety','health','emergency','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:50:00Z'::timestamptz, '2026-05-15T02:50:00Z'::timestamptz),
('How to Read Pet Food Guaranteed Analysis', 'The ''Guaranteed Analysis'' lists minimum levels of crude protein and fat, and maximum levels of fiber and moisture. However, these are measured by weight, including water. To compare wet and dry food fairly, you must calculate the ''Dry Matter Basis.'' High protein doesn''t always mean high quality; look for the source of that protein in the main ingredient list.', 'Understanding the percentages on the back of the bag to ensure balanced nutrition.', 'General', '📊', 9, ARRAY['nutrition','health','generic','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T02:55:00Z'::timestamptz, '2026-05-15T02:55:00Z'::timestamptz),
('Heatstroke in Dogs: A Summer Warning', 'Heatstroke can be fatal in minutes. Unlike humans, dogs only sweat through their paws and rely on panting to cool down. Symptoms include excessive panting, bright red gums, and lethargy. Never leave your dog in a parked car, even for a minute. If you suspect heatstroke, move them to the shade, apply cool (not ice-cold) water to their body, and rush to the vet.', 'How to recognize the signs of overheating in the Indian summer and act fast.', 'Canine', '☀️', 8, ARRAY['dogs','health','safety','India']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:00:00Z'::timestamptz, '2026-05-14T23:00:00Z'::timestamptz),
('Why Does My Dog Eat Grass?', 'Many owners worry when their dog grazes like a cow. Common theories include settling an upset stomach, fulfilling a fiber deficiency, or simply enjoying the taste of fresh spring grass. Most of the time, it''s normal behavior. However, ensure the grass hasn''t been treated with pesticides or fertilizers, and consult a vet if the grazing is followed by frequent vomiting.', 'Exploring the theories behind this common canine behavior.', 'Canine', '🌱', 5, ARRAY['dogs','behavior','health','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:05:00Z'::timestamptz, '2026-05-14T23:05:00Z'::timestamptz),
('The Importance of Vertical Space for Cats', 'Cats are both predators and prey, and being high up makes them feel secure. In multi-cat households, vertical space can reduce territorial tension. You don''t need expensive cat trees; cleared bookshelves, window perches, or wall-mounted ''cat shelves'' work perfectly. This allows them to survey their kingdom and retreat from household commotion like vacuums or guests.', 'Why your cat needs to climb and how to optimize small apartments.', 'Feline', '🪜', 7, ARRAY['cats','behavior','home','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:10:00Z'::timestamptz, '2026-05-14T23:10:00Z'::timestamptz),
('Why Cats Slow Blink at You', 'In the feline world, direct eye contact is a challenge. When a cat looks at you and slowly closes and opens their eyes, it''s a profound sign of trust and affection—essentially a ''cat kiss.'' You can reciprocate this behavior to tell a nervous cat you aren''t a threat. It’s one of the simplest ways to communicate love across species boundaries.', 'Decoding the ''cat kiss'' and how to use it to build trust.', 'Feline', '👁️', 4, ARRAY['cats','behavior','communication','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:15:00Z'::timestamptz, '2026-05-14T23:15:00Z'::timestamptz),
('Cycling a New Tank: The Nitrogen Cycle', 'Fish produce ammonia, which is toxic. ''Cycling'' a tank means growing beneficial bacteria that turn ammonia into nitrites, and then into less-harmful nitrates. This process typically takes 4–6 weeks. Never add all your fish at once to a brand-new tank; instead, use a ''fishless cycle'' with a pinch of fish food to feed the bacteria before your pets arrive.', 'The most important step in fishkeeping that most beginners skip.', 'Aquatic', '🔄', 12, ARRAY['aquarium','setup','maintenance','beginner']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:20:00Z'::timestamptz, '2026-05-14T23:20:00Z'::timestamptz),
('Signs of Freshwater Ich (White Spot Disease)', 'Ich looks like small grains of salt sprinkled over your fish''s body and fins. Affected fish may ''flash'' (rub against decor). It is highly contagious but treatable. Increasing the tank temperature slightly (to 30°C) can speed up the parasite''s life cycle, making it vulnerable to medications. Always quarantine new fish to prevent Ich from entering your main display tank.', 'Identifying and treating the most common aquarium parasite.', 'Aquatic', '🐟', 9, ARRAY['aquarium','health','maintenance','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:25:00Z'::timestamptz, '2026-05-14T23:25:00Z'::timestamptz),
('Safe Fruits for Parrots', 'Fruits are a great source of vitamins for birds, but should only be 10% of their diet due to sugar content. Safe options include apples (seeds removed), berries, and papaya. **NEVER** give a bird avocado, as it contains persin, which is highly toxic to them. Always wash fruit thoroughly to remove pesticides and serve in bite-sized pieces.', 'Healthy treat options and what to avoid (No avocado!)', 'Avian', '🍎', 6, ARRAY['birds','nutrition','safety','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:30:00Z'::timestamptz, '2026-05-14T23:30:00Z'::timestamptz),
('Feather Plucking: Stress or Medical?', 'Feather plucking is often a sign of psychological distress, boredom, or a lack of social interaction. However, it can also be caused by skin infections, parasites, or poor diet. Before assuming it''s behavioral, a vet check-up is vital. Improving environmental enrichment, ensuring 10-12 hours of sleep, and offering foraging toys can help break the habit.', 'Understanding the complex reasons why birds over-groom.', 'Avian', '🪶', 10, ARRAY['birds','behavior','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:35:00Z'::timestamptz, '2026-05-14T23:35:00Z'::timestamptz),
('Hamster Hibernation vs. Torpor', 'Pet hamsters don''t truly hibernate; they enter a dangerous state called ''torpor'' if their environment gets too cold. A torpid hamster will be limp and cold but may have a very faint heartbeat. Do not bury them! Slowly warm them up using your body heat or a heating pad on the lowest setting. Ensure their room stays above 20°C to prevent this from happening.', 'Why your hamster might look lifeless in the cold and how to save them.', 'Small Pet', '❄️', 8, ARRAY['hamsters','safety','health','emergency']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:40:00Z'::timestamptz, '2026-05-14T23:40:00Z'::timestamptz),
('Hedgehog Anointing: The Weirdest Behavior', 'If you see your hedgehog foaming at the mouth and licking their back, don''t panic! This is ''self-anointing.'' They do this when they encounter a new or interesting scent. They create a foamy saliva and spread it on their spines, possibly to camouflage their scent or as a defense mechanism. It''s perfectly normal, if a bit messy!', 'Why hedgehogs froth at the mouth and spread it on their quills.', 'Small Pet', '🦔', 5, ARRAY['hedgehogs','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:45:00Z'::timestamptz, '2026-05-14T23:45:00Z'::timestamptz),
('Traveling with Pets: Road Trip Tips', 'Preparation is key for a successful road trip. Use a secured crate or a pet seatbelt for safety. Pack a ''travel bag'' with their usual food, water, a favorite toy, and a first-aid kit. Take breaks every 2-3 hours for potty and stretching. For anxious pets, consult your vet about calming supplements or pheromone sprays before the journey.', 'Making long-distance travel comfortable for your furry companions.', 'General', '🚗', 9, ARRAY['travel','life','safety','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:50:00Z'::timestamptz, '2026-05-14T23:50:00Z'::timestamptz),
('The Environmental Impact of Pet Ownership', 'From plastic waste to meat-heavy diets, pets have an environmental impact. You can help by using biodegradable poop bags, choosing toys made from natural fibers, and buying food in bulk to reduce packaging. Spaying and neutering is also vital to prevent pet overpopulation. Small changes in how we care for our pets can lead to a healthier planet for all species.', 'How to reduce your pet''s carbon ''pawprint.''', 'General', '🌍', 7, ARRAY['life','generic','sustainability','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:55:00Z'::timestamptz, '2026-05-14T23:55:00Z'::timestamptz),
('Understanding Separation Anxiety in Dogs', 'Separation anxiety often manifests as destructive chewing, howling, or accidents near exits. To help, avoid big goodbyes or emotional reunions, which heighten the drama of your absence. Start with short ''practice'' departures—just 30 seconds—and reward calm behavior. Providing a long-lasting chew toy right before you leave can also help reassociate your departure with a positive experience.', 'How to help your dog feel safe when home alone.', 'Canine', '🏠', 10, ARRAY['dogs','behavior','training','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:00:00Z'::timestamptz, '2026-05-14T10:00:00Z'::timestamptz),
('The Dangers of Human Meds for Dogs', 'Never give your dog human medication without vet approval. NSAIDs like Ibuprofen or Naproxen can cause life-threatening stomach ulcers and kidney failure in dogs. Acetaminophen (Paracetamol) is equally dangerous and can damage red blood cells. If your dog is in pain, always seek a canine-specific prescription to ensure the dosage and compound are safe.', 'Why common painkillers like Ibuprofen are highly toxic to canines.', 'Canine', '💊', 6, ARRAY['dogs','health','safety','emergency']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:05:00Z'::timestamptz, '2026-05-14T10:05:00Z'::timestamptz),
('Cat Nip vs. Silver Vine', 'Approximately 30% of cats do not react to catnip. If your cat is one of them, try Silver Vine (Matatabi). It contains two active compounds compared to catnip’s one, and studies show it elicits a response in nearly 80% of felines. Both are safe, non-addictive, and provide excellent mental stimulation, leading to the classic rolling and ''happy'' behavior.', 'Alternative stimulants for cats who don''t react to traditional catnip.', 'Feline', '🌿', 5, ARRAY['cats','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:10:00Z'::timestamptz, '2026-05-14T10:10:00Z'::timestamptz),
('Managing Feline Kidney Disease', 'Chronic Kidney Disease (CKD) is common in older cats. Early signs include increased thirst and frequent urination. While CKD isn''t curable, it is manageable through a low-phosphorus diet and ensuring high hydration levels. Water fountains can encourage cats to drink more, and switching to wet food can significantly help maintain kidney function for longer.', 'Early warning signs and nutritional management for senior cats.', 'Feline', '💧', 11, ARRAY['cats','health','senior care','nutrition']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:15:00Z'::timestamptz, '2026-05-14T10:15:00Z'::timestamptz),
('Understanding Water Hardness (GH and KH)', 'General Hardness (GH) measures calcium and magnesium, vital for osmotic balance in fish. Carbonate Hardness (KH) measures the water''s ability to buffer pH—low KH can lead to dangerous ''pH crashes.'' In an aquascape, high hardness can cause mineral buildup on leaves. Testing your tap water is the first step in deciding which species will thrive in your specific local environment.', 'Why the mineral content of your water matters for your fish and plants.', 'Aquatic', '🧪', 12, ARRAY['aquarium','maintenance','chemistry','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:20:00Z'::timestamptz, '2026-05-14T10:20:00Z'::timestamptz),
('The Role of Snails in a Balanced Tank', 'Many hobbyists panic when they see small snails, but they are nature''s cleanup crew. They eat decaying plant matter and leftover food that would otherwise rot and spike ammonia. Their population only explodes if you are overfeeding. Instead of removing them, use them as a biological indicator—if you have too many snails, you are feeding too much.', 'Why ''pest'' snails like Bladder and Ramshorn are actually helpful.', 'Aquatic', '🐌', 6, ARRAY['aquarium','maintenance','species','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:25:00Z'::timestamptz, '2026-05-14T10:25:00Z'::timestamptz)
) AS v(title, content, summary, category, emoji, read_time_minutes, tags, thumbnail_url, is_published, author_name, view_count, created_at, updated_at)
WHERE NOT EXISTS (SELECT 1 FROM public.knowledge_articles k WHERE k.title = v.title AND coalesce(k.summary,'') = coalesce(v.summary,''));